"""
Dienst zum Hinzufuegen von Vouchern zu Subscriptions ueber die eSuite API.
"""

import logging
from datetime import datetime

import pandas as pd

from ..config_service import get_esuite_api_config
from ..db.db_service import execute_dataframe_query
from ..utils.http_utils import retry_request
from ..utils.progress_logging import iter_with_progress
from .esuite_client import convert_id

logger = logging.getLogger(__name__)


def run_add_voucher() -> pd.DataFrame:
    """Ergänzt fehlende Voucher für berechtigte Subscriptions aus der Datenbank.

    Lädt die für die Preisanpassung vorgemerkten Subscriptions ohne Voucher und
    fügt den konfigurierten Voucher über die eSuite-API hinzu.

    Returns:
        DataFrame mit Ausführungs-ID sowie Anzahl der gefundenen und
        erfolgreich aktualisierten Subscriptions.
    """
    execution_time = datetime.now()
    execution_id = int(execution_time.timestamp())

    query = """
    SELECT distinct
    substr(sub.Payer,-9) ACCOUNTID,
    sub.SubscriptionId SUBSCRIPTIONID,
    '356AMJ3J6J' VOUCHER
    FROM dbm_lesermarkt.tb_subscriptionsreport_ff sub
    WHERE subscriptionid IN (SELECT subscriptionid FROM tb_Preisanpassung_WB_Tablet)
    AND subscriptionstatusid = 2
    AND VoucherCode IS null
    """

    subscriptions_df = get_sub(query)
    total_to_update = len(subscriptions_df)
    successful_updates = 0

    for _index, row in iter_with_progress(
        logger, subscriptions_df.iterrows(), len(subscriptions_df), "Voucher-Subscriptions"
    ):
        logger.info(f"Row data: {row.to_dict()}")
        accid = row["ACCOUNTID"]
        subid = row["SUBSCRIPTIONID"]
        voucher_code = row["VOUCHER"]
        logger.info(f"Processing subscription {subid} for account {accid} with voucher {voucher_code}.")

        success = add_voucher(accid, subid, voucher_code)
        if success:
            successful_updates += 1
            logger.info(f"Successfully added voucher {voucher_code} to subscription {subid}.")
        else:
            logger.error(f"Failed to add voucher {voucher_code} to subscription {subid}.")

    logger.info(f"Voucher addition process completed. Successful: {successful_updates}/{total_to_update}")

    result_df = pd.DataFrame(
        [
            {
                "successful_updates": successful_updates,
                "total_to_update": total_to_update,
                "execution_time": execution_time,
                "execution_id": execution_id,
            }
        ]
    )

    return result_df


def get_sub(query: str) -> pd.DataFrame:
    """Ruft alle Subscriptions aus der PROD-Umgebung ab und gibt sie als DataFrame zurück.

    Args:
        query (str): SQL-Query zum Abrufen der Subscriptions

    Returns:
        pd.DataFrame: DataFrame mit den abgerufenen Subscriptions.
    """
    try:
        return execute_dataframe_query(query)
    except Exception as e:
        logger.exception(f"Error fetching subscriptions: {e}")
        return pd.DataFrame()


def check_sub(accid: str, subid: str) -> bool:
    """Überprüft den status einer Subscription anhand der SubscriptionID.

    Args:
        accid (str): Die AccountID, zu der die Subscription gehört.
        subid (str): Die SubscriptionID, die überprüft werden soll.

    Returns:
        bool: True wenn sicher zum Hinzufügen, False andernfalls.
    """
    api_config = get_esuite_api_config("PROD")
    headers = api_config.headers
    resthost = api_config.resthost

    url = f"{resthost}accounts/{accid}/subscriptions"
    subscriptionreference = convert_id("Prod", subid, "S")

    try:
        response = retry_request("GET", url, headers=headers, verify=False)
        if response is None:
            logger.error(f"Keine Antwort für Account {accid}")
            return False
        logger.debug(f"GET {url} -> status {response.status_code}")
        data = response.json()
        if isinstance(data, list):
            subscriptions = data
        elif isinstance(data, dict):
            subscriptions = data.get("value", data)
            if isinstance(subscriptions, dict):
                subscriptions = [subscriptions]
        else:
            logger.error("Unerwartetes Antwortformat fuer Account %s: %s", accid, type(data).__name__)
            return False
        for sub in iter_with_progress(logger, subscriptions, len(subscriptions), f"Subscriptions fuer Account {accid}"):
            if not isinstance(sub, dict):
                logger.warning("Ueberspringe unerwarteten Subscription-Eintrag: %s", type(sub).__name__)
                continue
            ref = sub.get("recurringPaymentInfo", {}).get("subscriptionReference")
            logger.debug(f"Found subscriptionReference={ref} (looking for {subscriptionreference})")
            if ref == subscriptionreference:
                voucher_codes = sub.get("recurringPaymentInfo", {}).get("subscriptionVoucherCodes", [])
                discount_price = sub.get("recurringPaymentInfo", {}).get("voucherCodes", {}).get("discountPrice")
                if voucher_codes:
                    logger.info(f"Subscription {subid}: voucher codes present: {voucher_codes} (not safe to add)")
                    return False
                elif discount_price and discount_price != 0:
                    logger.info(f"Subscription {subid}: discountPrice={discount_price} (not safe to add)")
                    return False
                else:
                    logger.info(
                        "Subscription %s: no voucher codes present, discountPrice=%s (safe to add)",
                        subid,
                        discount_price,
                    )
                    return True
        logger.info(f"Subscription {subid} not found in account {accid}")
        return False
    except Exception as e:
        logger.exception(f"Error checking subscription {subid}: {e}")
        return False
    finally:
        logger.debug(f"Completed check_sub for account={accid} subid={subid}")


def add_voucher(accid: str, subid: str, voucher_code: str) -> bool:
    """Fügt einer Subscription einen Voucher hinzu.

    Args:
        accid (str): Die AccountID, zu der die Subscription gehört.
        subid (str): Die SubscriptionID, der der Voucher hinzugefügt werden soll.
        voucher_code (str): Der Voucher-Code, der hinzugefügt werden soll.

    Returns:
        bool: True, wenn der Voucher erfolgreich hinzugefügt wurde, sonst False.
    """
    check = check_sub(accid, subid)
    logger.info(f"Check result for subscription {subid}: {check}")
    if not check:
        logger.info(f"Subscription {subid} already has a voucher or could not be checked.")
        return False

    api_config = get_esuite_api_config("PROD")
    headers = api_config.headers
    resthost = api_config.resthost
    url = f"{resthost}accounts/{accid}/subscriptions/{subid}"
    logger.info(f"Adding voucher to: {url}")

    body = [{"op": "add", "path": "/VoucherCode", "value": str(voucher_code)}]
    logger.info(f"Request body: {body}")
    try:
        response = retry_request("PATCH", url, json=body, headers=headers, verify=False)
        if response is None:
            logger.error(f"Keine Antwort beim Hinzufügen von Voucher {voucher_code} zu Subscription {subid}")
            return False
        logger.debug(f"PATCH {url} -> status {response.status_code}")
        if response.status_code in [200, 201, 204]:
            logger.info(f"Added voucher {voucher_code} to subscription {subid} (status {response.status_code})")
            return True
        else:
            logger.error(
                "Failed to add voucher %s to subscription %s: %s - %s",
                voucher_code,
                subid,
                response.status_code,
                response.text,
            )
            return False
    except Exception as e:
        logger.exception(f"Exception while adding voucher {voucher_code} to subscription {subid}: {e}")
        return False
